INSERT INTO questions (id, topic_id, question, options, correct_index, difficulty, explanation) VALUES ('22955a87-1695-469c-82aa-a39bfefa1b50','71a436e2-4d33-464a-8ca3-e7894ed57218','A 5 kg body experiences a net force of 20 N. Its acceleration is:','["2 m/s\u00b2", "4 m/s\u00b2", "5 m/s\u00b2", "20 m/s\u00b2"]'::jsonb,1,'easy','a = F/m = 20/5 = 4 m/s²');
