INSERT INTO questions (id, topic_id, question, options, correct_index, difficulty, explanation) VALUES ('5ee42737-2346-43cf-aa1d-2d6c0eb7c675','71a436e2-4d33-464a-8ca3-e7894ed57218','A car of 1000 kg accelerates from 0 to 20 m/s in 10 s. Net force =','["1000 N", "2000 N", "5000 N", "10000 N"]'::jsonb,1,'medium','a=2 m/s², F=ma=1000×2=2000 N');
