INSERT INTO questions (id, topic_id, question, options, correct_index, difficulty, explanation) VALUES ('51941032-f0a0-4ee5-af51-1bc418b7687d','71a436e2-4d33-464a-8ca3-e7894ed57218','Two bodies of masses 2 kg and 3 kg are connected over a pulley. Net acceleration (g=10):','["1 m/s\u00b2", "2 m/s\u00b2", "4 m/s\u00b2", "6 m/s\u00b2"]'::jsonb,1,'hard','a=(m₂−m₁)g/(m₁+m₂) = 10/5 = 2 m/s²');
