INSERT INTO questions (id, topic_id, question, options, correct_index, difficulty, explanation) VALUES ('43a94436-a079-491a-9882-4fd18fceb1be','42ddfff5-ad1f-408d-b3d8-5e9bf76439cd','Electric flux through closed surface (Gauss):','["Q", "Q/\u03b5\u2080", "Q\u03b5\u2080", "0"]'::jsonb,1,'hard','Φ = Q_enc / ε₀');
